// Baut Such-Queries pro Region (Vereinsjubiläum + Festwirt)
// Regionen kommen aus vorherigem Node
const regions = $json.regions || ['Ingolstadt','Kelheim','Regensburg','München'];
const runId = $json.runId || '';
const minScore = $json.minScore || 60;

const templates = [
  (r) => `Vereinsjubiläum 125 Jahre Festwirt gesucht ${r} 2027`,
  (r) => `Vereinsjubiläum 100 Jahre Festwirt gesucht ${r} 2028`,
  (r) => `Schützenfest 100 Jahre Festwirt Ausschreibung ${r}`,
  (r) => `Trachtenfest Jubiläum Festwirt gesucht ${r} 2027 OR 2028`,
  (r) => `Feuerwehrfest Jubiläum Festwirt gesucht ${r}`,
  (r) => `Volksfest Festwirt Ausschreibung ${r} 2027 2028`,
  (r) => `Kirchweih Festwirt gesucht ${r} 2027`,
  (r) => `Musikfest Jubiläum Festwirt gesucht ${r}`,
];

const items = [];
for (const region of regions) {
  for (const tpl of templates) {
    items.push({ json: { query: tpl(region), region, runId, minScore } });
  }
}
return items;

// Tavily-Antwort: results[] -> einzelne Items je Treffer (mit raw_content als Text)
const items = [];
for (const item of $input.all()) {
  const src = item.pairedItem?.item?.json || {};
  const query = src.query || item.json.query || '';
  const region = src.region || '';
  const runId = src.runId || '';
  const minScore = src.minScore || 60;
  const results = item.json.results || [];
  for (const hit of results.slice(0, 6)) {
    if (!hit.url) continue;
    const url = hit.url;
    if (/\.(jpg|jpeg|png|gif|bmp|webp|mp4|mp3|pdf)(\?.*)?$/i.test(url)) continue;
    const raw = (hit.raw_content || hit.content || '').replace(/\s+/g, ' ').trim();
    items.push({
      json: {
        url,
        title: hit.title || '',
        snippet: (raw || hit.content || '').slice(0, 2000),
        text: raw ? raw.slice(0, 6000) : '',
        score: hit.score ?? null,
        query,
        region,
        runId,
        minScore
      }
    });
  }
}
return items;

// HTML zu Text machen + kürzen + URL-Kontext behalten
let html = '';
try {
  const data = $json.data;
  html = typeof data === 'string' ? data : (data?.toString?.() || JSON.stringify(data || ''));
} catch(e) { html = ''; }

// Skripte + Styles raus
let text = html.replace(/<(script|style)[^>]*>[\s\S]*?<\/\1>/gi, ' ');
text = text.replace(/<[^>]+>/g, ' '); // Tags raus
text = text.replace(/&nbsp;|&#160;/g, ' ')
           .replace(/&amp;/g, '&').replace(/&quot;/g, '"')
           .replace(/&#39;|&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>')
           .replace(/\s+/g, ' ').trim();

if (!text || text.length < 200) {
  // Zu wenig Inhalt -> skip (wird beim nächsten Node gefiltert)
  text = '';
}

return [{
  json: {
    url: $('Suchtreffer parsen').item.json.url,
    title: $('Suchtreffer parsen').item.json.title || '',
    snippet: $('Suchtreffer parsen').item.json.snippet || '',
    region: $('Suchtreffer parsen').item.json.region || '',
    runId: $('Suchtreffer parsen').item.json.runId || '',
    minScore: $('Suchtreffer parsen').item.json.minScore || 60,
    text: text.slice(0, 4000)
  }
}];

// LLM-Antwort parsen, Score filtern, Datum-Check, nur valide Items weiter
const today = new Date('2026-11-07T00:00:00Z');
const minScore = 60;
const out = [];

for (const item of $input.all()) {
  let content = '';
  try {
    content = item.json.choices?.[0]?.message?.content || item.json.message?.content || '';
  } catch(e) {}
  if (!content) continue;
  // Markdown-Codefence entfernen
  content = content.replace(/```json|```/gi, '').trim();
  let parsed;
  try { parsed = JSON.parse(content); } catch(e) { continue; }
  if (!parsed || typeof parsed.score !== 'number') continue;
  if (parsed.score < minScore) continue;
  if (parsed.festwirtStatus === 'taken' || parsed.festwirtStatus === 'closed') continue;

  // Datum-Check: >36 Monate zu früh -> skip; <4 Monate -> skip (außer Notfall im Reason)
  if (parsed.eventDate) {
    const d = new Date(parsed.eventDate + 'T00:00:00Z');
    if (!isNaN(d)) {
      const months = (d - today) / (1000*60*60*24*30.44);
      if (months > 36) continue;
      if (months < 4 && !/notfall|abgesprungen|frei|offen.*kurzfristig/i.test(parsed.scoreReason || '')) continue;
      parsed.monthsAhead = Math.round(months);
    }
  }
  parsed.sourceUrl = parsed.sourceUrl || ($('Suchtreffer parsen').item?.json?.url || '');
  parsed.runId = $('Suchtreffer parsen').item?.json?.runId || '';
  parsed.status = 'new';
  parsed.discoveredAt = new Date().toISOString();
  out.push({ json: parsed });
}
return out;
